  fleetScene.add(shadows);

  const visible=()=>win(9.65,9.96,10.23,10.54);
  const focus=()=>sst(.18,.34,ZFs);
  const grouped=[{name:"통합 진에어",count:60,color:LJ,center:FLC.jin,labelZ:67},...groups.filter(g=>!g.detail)];
  for(const group of [...grouped,...groups.filter(g=>g.detail)]){
    label(group.name+" "+group.count+"대","fleet",
      ()=>V(group.center.x,8,group.labelZ),
      ()=>visible()*(group.detail?focus():1-focus()),group.color);
  }
