  launchKick=Math.max(0,launchKick-dt*.5);
  if(autoOn){if(lastA){window.scrollBy(0,(now-lastA)*AUTO_SPEED*(Ts<1.1?.55:1));}lastA=now;if(vnScroll()+innerHeight>=ROOT.querySelector(".fact").offsetTop+40){stopAuto();}}
